fn binary_search(v: &Vec<u64>, k: u64) -> usize {
    let mut left = 0;
    let mut right = v.len() - 1;

    while left <= right {
        let mid = left + (right - left) / 2;
        let mid_val = v[mid];

        if mid_val == k {
            return mid;
        } else if mid_val < k {
            left = mid + 1;
        } else {
            // mid_val > k
            if mid == 0 {
                // This prevents underflow if mid is 0
                break;
            }
            right = mid - 1;
        }
    }

    // According to the problem assumptions, k is guaranteed to be in v,
    // so this point should never be reached.
    // Still, return left as a fallback (left must be valid index)
    left
}